ALTER TABLE public.discovered_playlists ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'deezer'; ALTER TABLE public.discovered_playlists ADD COLUMN IF NOT EXISTS updated_at timestamp with time zone NOT NULL DEFAULT now(); DELETE FROM public.discovered_playlists a USING public.discovered_playlists b WHERE a.ctid < b.ctid AND a.seed_track_id = b.seed_track_id AND a.playlist_id = b.playlist_id; CREATE UNIQUE INDEX IF NOT EXISTS discovered_playlists_seed_playlist_key ON public.discovered_playlists (seed_track_id, playlist_id); CREATE INDEX IF NOT EXISTS discovered_playlists_source_idx ON public.discovered_playlists (source); DROP POLICY IF EXISTS "Authenticated users can update discovered playlists" ON public.discovered_playlists; CREATE POLICY "Authenticated users can update discovered playlists" ON public.discovered_playlists FOR UPDATE TO authenticated USING (auth.uid() IS NOT NULL) WITH CHECK (auth.uid() IS NOT NULL);